const TEAL = '#1b3a4b';
const FOAM = '#e6f4fb';
const SUN = '#ffd23c';
const BOOK = 'M4 5.5A2.5 2.5 0 0 1 6.5 3H20v15H6.5A2.5 2.5 0 0 0 4 20.5zM4 20.5A2.5 2.5 0 0 0 6.5 23H20v-5';

function meaning(word) {
  const definition = (word.definition || '').trim();
  const stop = /[.!?]$/.test(definition) ? '' : '.';
  return definition + stop + (word.example ? ' "' + word.example + '"' : '');
}

// Know it's fill sits twice: solid in the backdrop, which tinted and clear mode remove, and faint in the tree.
// So in full color it reads as one solid key, and in tinted mode its words still show on the faint one. The
// backdrop draws the same keys with their words hidden, so both line up.
function keys(word, u, ghost) {
  const key = (action, label, fill, color) => ({ type: ghost ? 'zstack' : 'button', action: ghost ? null : action,
    rowId: ghost ? null : word.id, children: [
      { type: 'hstack', spacing: 4 * u, padding: { vertical: 6 * u, horizontal: 11 * u },
        background: { type: 'rect', cornerRadius: 10 * u, fill }, children: [
          word.verdict === action && { type: 'symbol', name: 'checkmark', size: 10 * u, weight: 'heavy', color,
            opacity: ghost ? 0 : 1 },
          { type: 'text', value: label, size: 12 * u, weight: 'bold', color, opacity: ghost ? 0 : 1 },
        ] } ] });
  return { type: 'hstack', spacing: 7 * u, padding: { leading: 16 * u, bottom: 14 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottomLeading' },
    children: [
      key('know', 'Know it', ghost ? SUN : '#ffd23c40', TEAL),
      key('again', 'Again', ghost ? '#1b3a4b00' : '#FFFFFF21', FOAM),
    ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size, so
  // the gaps around the word are 0.1 of its size shorter than the prototype's.
  const u = ctx.height / 170;
  const d = ctx.data;
  const word = d.word;
  const wide = ctx.family === 'medium';

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: TEAL,
      children: [word && keys(word, u, true)] },
    children: [
      { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 15 * u, leading: 16 * u, trailing: 16 * u },
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          { type: 'hstack', spacing: 5 * u, frame: { height: 16 * u }, children: [
            { type: 'path', d: BOOK, viewBox: [0, 0, 24, 24], frame: { width: 15 * u, height: 15 * u },
              stroke: { color: SUN, width: 2.4 * 15 * u / 24 } },
            { type: 'text', value: 'Palabra del día', size: 13 * u, weight: 'bold', color: SUN, lineLimit: 1,
              minScale: 0.8 },
            { type: 'spacer', minLength: 0 },
            wide && { type: 'text', value: d.learned + ' learned', size: 13 * u, weight: 'semibold', color: SUN,
              opacity: 0.55, lineLimit: 1 },
          ] },
          { type: 'text', value: word ? word.word || '?' : 'pronto', fontName: 'Bricolage Grotesque Display',
            size: 40 * u, kerning: -1.2 * u, color: SUN, accent: true, lineLimit: 1, minScale: 0.4,
            padding: { top: 4 * u } },
          { type: 'text', value: word ? meaning(word) : 'soon. Your first word lands here at 6:00.',
            size: 12.5 * u, weight: 'semibold', color: FOAM, opacity: 0.8, lineLimit: 2, minScale: 0.8,
            padding: { top: 1 * u }, frame: { maxWidth: (ctx.width - 32 * u) * 0.92, alignment: 'leading' } },
        ] },
      word && keys(word, u, false),
    ],
  };
}
